const listMoviesForTrailers = `-- name: ListMoviesForTrailers :many
SELECT m.id, m.tmdb_id FROM movies m
WHERE (COALESCE(m.trailers_checked_at, '') < CAST(?1 AS TEXT)
       OR (m.release_date >= CAST(?2 AS TEXT)
           AND COALESCE(m.trailers_checked_at, '') < CAST(?3 AS TEXT)))
  AND EXISTS (SELECT 1 FROM media_files f WHERE f.movie_id = m.id AND f.status = 'present')
ORDER BY m.trailers_checked_at, m.id
LIMIT ?4
`

type ListMoviesForTrailersParams struct {
	OlderBefore  string `json:"older_before"`
	RecentSince  string `json:"recent_since"`
	RecentBefore string `json:"recent_before"`
	MaxRows      int64  `json:"max_rows"`
}

type ListMoviesForTrailersRow struct {
	ID     int64 `json:"id"`
	TmdbID int64 `json:"tmdb_id"`
}

// Movies with a file on disk whose TMDB trailers are due a check
// (PLAN-TRAILERS.md 5.1), never checked first, then the longest since.
// Movies released on or after recent_since, or not yet released, are due
// once last checked before recent_before; every movie is due once last
// checked before older_before, which is earlier. Never checked (”) is
// before both. It reads every movie (a few thousand rows), a few times a
// day.
func (q *Queries) ListMoviesForTrailers(ctx context.Context, arg ListMoviesForTrailersParams) ([]ListMoviesForTrailersRow, error) {
	rows, err := q.db.QueryContext(ctx, listMoviesForTrailers,
		arg.OlderBefore,
		arg.RecentSince,
		arg.RecentBefore,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListMoviesForTrailersRow{}
	for rows.Next() {
		var i ListMoviesForTrailersRow
		if err := rows.Scan(&i.ID, &i.TmdbID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

